// Sem Destino site: English first, Portuguese on request. Text nodes are matched against /sao-paulo/i18n_pt.json (English -> Portuguese);
// numbers-with-words lines generated by the page scripts are handled by the patterns below. The choice is remembered per browser.
(function(){
  const KEY="sd_lang";let lang="en";
  try{lang=localStorage.getItem(KEY)||((navigator.language||"").toLowerCase().startsWith("pt")?"pt":"en")}catch(e){}
  let PT=null,OBS=null;const ORIG=new WeakMap(),ATTR=new WeakMap();let busy=false;
  const ptNum=s=>s.replace(/(\d),(\d{3})/g,"$1.$2").replace(/(\d)\.(\d{3})(?!\d)/g,(m,a,b)=>a+"."+b);
  const RULES=[
    [/^(\d[\d,.]*) one-way of (\d[\d,.]*) road pieces · (\d+) signals(.*)$/,(m,a,b,c,r)=>`${a} de ${b} trechos em mão única · ${c} semáforos`+r.replace(/ · (\d+) bus lanes/," · $1 faixas de ônibus").replace(/ · (\d+) speed cameras/," · $1 radares")],
    [/^(.*) · (-?[\d.]+) km E, (-?[\d.]+) km N of MASP$/i,(m,a,x,y)=>`${a} · ${x} km L, ${y} km N do MASP`],
    [/^(.*) km E, (-?[\d.]+) km N of MASP(.*)$/,(m,a,y,r)=>`${a} km L, ${y} km N do MASP${r}`],
    [/^(T_\S+) · grade ([A-F])$/,(m,t,g)=>`${t} · nota ${g}`],
    [/^In-game render · (T_\S+)(.*)$/,(m,t,r)=>`Render do jogo · ${t}${r}`],
    [/^Hand-built landmark · in-game render(.*)$/,(m,r)=>`Marco feito à mão · render do jogo${r}`],
    [/^Four blocks built: ([\d,]+) tiles$/,(m,a)=>`Quatro blocos construídos: ${ptNum(a)} tiles`],
    [/^(\w+) blocks built: ([\d,]+) tiles$/,(m,w,a)=>`Blocos construídos: ${ptNum(a)} tiles`],
    [/^([\d,]+) tiles of 500 m$/,(m,a)=>`${ptNum(a)} tiles de 500 m`],[/^(\d+) blocks$/,(m,a)=>`${a} blocos`],[/^(\d+) rail lines$/,(m,a)=>`${a} linhas sobre trilhos`],
    [/^([\d,]+) named streets$/,(m,a)=>`${ptNum(a)} ruas com nome`],[/^street · (\d+) tiles?$/,(m,a)=>`rua · ${a} tiles`],[/^neighbourhood · (\d+) tiles?$/,(m,a)=>`bairro · ${a} tiles`],
  ];
  function tr(s){const k=s.trim();if(!k)return null;const hit=PT[k];if(hit!=null)return s.replace(k,hit);for(const [re,f] of RULES){if(re.test(k))return s.replace(k,k.replace(re,f))}return null}
  function walk(root){const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT,{acceptNode:n=>{const p=n.parentNode&&n.parentNode.nodeName;return(p==="SCRIPT"||p==="STYLE"||p==="CODE"||p==="PRE")?NodeFilter.FILTER_REJECT:NodeFilter.FILTER_ACCEPT}});
    let n;while((n=w.nextNode())){if(!ORIG.has(n))ORIG.set(n,n.nodeValue);const o=ORIG.get(n);let v=o;if(lang==="pt"){const t=tr(o);if(t!=null)v=t}if(n.nodeValue!==v)n.nodeValue=v}
    (root.querySelectorAll?root.querySelectorAll("[placeholder],[aria-label],[title]"):[]).forEach(el=>{for(const a of ["placeholder","aria-label","title"]){if(!el.hasAttribute(a))continue;let m=ATTR.get(el);if(!m){m={};ATTR.set(el,m)}if(!(a in m))m[a]=el.getAttribute(a);const o=m[a],t=lang==="pt"?tr(o):null,v=t==null?o:t;if(el.getAttribute(a)!==v)el.setAttribute(a,v)}})}
  function apply(){if(!PT&&lang==="pt")return;busy=true;document.documentElement.lang=lang==="pt"?"pt-BR":"en";walk(document.body);
    if(!document.__t0)document.__t0=document.title;document.title=lang==="pt"?(tr(document.__t0)||document.__t0):document.__t0;
    document.querySelectorAll(".langsw button").forEach(b=>b.setAttribute("aria-pressed",b.dataset.l===lang?"true":"false"));if(OBS)OBS.takeRecords();busy=false}
  function set(l){lang=l;try{localStorage.setItem(KEY,l)}catch(e){}if(l==="pt"&&!PT)load().then(apply);else apply()}
  function load(){return fetch("/sao-paulo/i18n_pt.json").then(r=>r.json()).then(d=>{PT=d}).catch(()=>{})}
  function addSwitch(){const bar=document.querySelector(".sb-in");if(!bar||bar.querySelector(".langsw"))return;const d=document.createElement("div");d.className="langsw";d.setAttribute("role","group");d.setAttribute("aria-label","Language");
    d.innerHTML='<button data-l="en" aria-pressed="true">EN</button><button data-l="pt" aria-pressed="false">PT</button>';d.querySelectorAll("button").forEach(b=>b.onclick=()=>set(b.dataset.l));
    const drive=bar.querySelector(".drivebtn");drive?bar.insertBefore(d,drive):bar.appendChild(d)}
  const css=document.createElement("style");css.textContent=".langsw{display:flex;border:1px solid rgba(255,255,255,.18);border-radius:999px;overflow:hidden;flex:none}.langsw button{background:none;border:0;color:inherit;font:700 12px/1 'JetBrains Mono',ui-monospace,monospace;letter-spacing:.06em;padding:7px 10px;cursor:pointer;opacity:.6}.langsw button[aria-pressed=true]{background:rgba(255,255,255,.14);opacity:1}";
  document.head.appendChild(css);
  function fix(n){ORIG.set(n,n.nodeValue);const t=tr(n.nodeValue);if(t!=null&&t!==n.nodeValue)n.nodeValue=t}
  function start(){addSwitch();OBS=new MutationObserver(ms=>{if(busy||lang!=="pt"||!PT)return;busy=true;for(const m of ms){if(m.type==="characterData"){if(m.target.nodeType===3)fix(m.target)}else m.addedNodes.forEach(n=>{if(n.nodeType===3)fix(n);else if(n.nodeType===1)walk(n)})}OBS.takeRecords();busy=false});OBS.observe(document.body,{childList:true,subtree:true,characterData:true});
    if(lang==="pt")load().then(apply);else apply()}
  document.readyState==="loading"?document.addEventListener("DOMContentLoaded",start):start();
})();
